def _skip_this_key(self, level, key):
    # if include_paths is not set, then include every path
    if self.include_paths is None:
        return False

    # Check if this specific key path is included
    key_path = "{}['{}']".format(level.path(), key)
    if key_path in self.include_paths:
        return False

    # Check if the level path itself is included (for cases like root['foo']['bar'] where we want to include all subpaths)
    if level.path() in self.include_paths:
        return False

    # Check if this key path matches any prefix in include_paths
    for prefix in self.include_paths:
        if key_path in prefix:
            return False

    # Check if any parent level is included
    up = level.up
    while up is not None:
        if up.path() in self.include_paths:
            return False
        up = up.up

    # If none of the above conditions match, skip this key
    return True
